        s1_p2: "Ensuite, pour chaque arête blanche : tourne la face du haut (U) jusqu'à ce que sa couleur latérale corresponde au centre en dessous, puis tourne cette face deux fois (ex. F2). Après les quatre, une croix blanche apparaît en bas, alignée avec les centres.",
        s1_c1: "Marguerite : arêtes blanches autour du centre jaune",
