        s3_right: "Si elle va à droite :",
        s3_left: "Si elle va à gauche :",
        s3_p2: "Si une arête du milieu est mal placée ou retournée, amène-la en avant-droite et fais l'algorithme de droite une fois ; l'arête remonte.",
