        s1_title: "الخطوة 1 — الصليب الأبيض",
        s1_p1: "اصنع أولًا الزهرة: ضع الحواف البيضاء الأربع حول المركز الأصفر والأبيض للأعلى. لا توجد خوارزمية هنا؛ ارفع الحواف إلى الأماكن الفارغة حول المركز الأصفر.",
        s1_p2: "ثم لكل حافة بيضاء: دوّر الطبقة العليا (U) حتى يطابق لونها الجانبي المركز الذي تحتها، ثم دوّر ذلك الوجه مرتين (مثل F2). بعد الأربع يظهر صليب أبيض في الأسفل مطابق للمراكز.",
        s1_c1: "الزهرة: حواف بيضاء حول المركز الأصفر",
        s1_c2: "النتيجة: صليب أبيض في الأسفل (منظر من الأسفل)",
