                a2: "Nein. Anfängeranleitung, Videos, alle Algorithmus-Seiten, der Trainer und die Druckblätter sind kostenlos. Nur die Einzelcoaching-Sitzungen kosten etwas.",
                q3: "Ich kann den Würfel gar nicht lösen. Wo fange ich an?",
                a3: "Starte mit der 3x3-Anfängeranleitung. Lerne zuerst die Notation und folge dann den 7 Schritten der Reihe nach; insgesamt musst du nur 6 Algorithmen auswendig lernen.",
                q4: "Welche Algorithmen lerne ich nach der Anfängermethode?",
                a4: "Beim 3x3 lernt man meist zuerst PLL, dann OLL. Sitzen diese, kannst du zu fortgeschrittenen Sets wie COLL und Winter Variation übergehen. Beim 2x2 beginnst du mit Ortega OLL und PBL und gehst dann zu CLL und EG.",
                q5: "Was bedeuten Buchstaben wie R, U' und M2?",
                a5: "Das ist die Würfelnotation: Jeder Buchstabe steht für das Drehen einer Seite. Ein einzelner Buchstabe ist eine Vierteldrehung im Uhrzeigersinn, ein Apostroph (') gegen den Uhrzeigersinn und 2 eine halbe Drehung. Der Notationsteil der Anfängeranleitung erklärt alles mit Bildern.",
                q6: "Wie funktioniert der Algorithmus-Trainer?",
                a6: "Du wählst ein Set und die Fälle, die du üben willst. Der Trainer gibt dir einen Scramble; du wendest ihn auf einen gelösten Würfel an und führst dann den Algorithmus auf Zeit aus. Fälle, die du als „Schwer“ markierst, kommen öfter. Ohne Würfel übst du im Kartenmodus nur das Abrufen des Algorithmus.",
                q7: "Kann ich einen Smart-Cube (Bluetooth) verbinden?",
                a7: "Ja. GAN Smart-Cubes (z. B. GAN 12 ui, GAN 356 i-Serie) lassen sich mit dem Trainer verbinden; die Zeit startet mit deinen Zügen und stoppt, wenn der Fall gelöst ist. Dafür brauchst du Chrome oder Edge auf Android oder dem Computer. Browser auf iPhone und iPad unterstützen kein Bluetooth.",
                q8: "Wo werden mein Fortschritt und meine Statistiken gespeichert?",
                a8: "Deine Markierungen „Lerne ich / Kann ich“, die Trainer-Statistiken und das Fortschrittsdiagramm werden im verwendeten Browser gespeichert. Ein Konto ist nicht nötig, aber auf einem anderen Gerät siehst du sie nicht. Löschst du die Browserdaten, werden sie ebenfalls gelöscht.",
                q9: "Kann ich die Seite wie eine App aufs Handy installieren?",
                a9: "Ja. Wähle auf Android im Chrome-Menü „App installieren“ oder „Zum Startbildschirm hinzufügen“. Tippe auf dem iPhone in Safari auf Teilen und wähle „Zum Home-Bildschirm“. Die Seite öffnet sich dann wie eine App.",
                q10: "Funktioniert sie ohne Internet?",
                a10: "Nachdem du die Seite einmal mit Internet geöffnet hast, funktionieren die Algorithmus-Seiten, der Trainer und die Anfängeranleitung auch offline. Für Videos brauchst du Internet.",
                q11: "Wie drucke ich die Algorithmen aus?",
                a11: "Für OLL, PLL und CLL gibt es fertige einseitige A4-Blätter. Wähle auf der Druckseite ein Set und drücke „Drucken / PDF“; wähle im Druckdialog „Als PDF speichern“, um eine PDF-Datei zu erhalten.",
                q12: "Für welche Puzzles gibt es Coaching?",
                a12: "Einzelcoaching gibt es für 2x2, 3x3, 3x3 einhändig, Skewb und Megaminx. Die Coaches und aktuellen Preise findest du auf der Coaching-Seite.",
                q13: "Wie buche ich eine Coaching-Sitzung?",
                a13: "Drücke auf der Coaching-Seite neben dem gewünschten Puzzle auf „Kaufen“. Die Zahlung läuft sicher über Shopier.",
                q14: "Wie wird der Termin festgelegt?",
                a14: "Nach der Zahlung legen wir den Termin gemeinsam mit dir fest.",
                q15: "Wie erreiche ich euch bei Fragen?",
                a15: "Schreib uns auf Instagram an @rubikacademyy.",
